const outbox=[],syncClients=new Set(),changeLog=[]
const folderNames=['INBOX','Archive','Drafts','Sent Messages','Junk','Deleted Messages','Clients'],moves=new Map()
let sequence=2,nextUID=800
const waitMutation=op=>new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{events.off('mutation',listener);reject(new Error('No mutation '+op))},10000);const listener=data=>{if(data.op===op){clearTimeout(timeout);events.off('mutation',listener);resolve(data)}};events.on('mutation',listener)})
const metadata=email=>({...email,key:(email.folder||'INBOX')+'|7|'+email.id,folder:email.folder||'INBOX',threadId:email.threadId||'thread-'+email.id,syncId:email.syncId||1})
const folderDetails=()=>folderNames.map(name=>({key:'folder-'+name,name,role:({'INBOX':'inbox','Archive':'archive','Drafts':'drafts','Sent Messages':'sent','Junk':'junk','Deleted Messages':'trash','Snoozed':'snoozed'})[name]||'',total:emails.filter(email=>(email.folder||'INBOX')===name).length,unread:emails.filter(email=>(email.folder||'INBOX')===name&&email.unread).length,imported:emails.filter(email=>(email.folder||'INBOX')===name).length,complete:true,ready:true,uidValidity:7}))
const publish=change=>{change={...change,syncId:++sequence};if(change.message){change.message.syncId=change.syncId;change.message.actor=change.actor;const raw=emails.find(email=>email.id===change.message.id);if(raw){raw.syncId=change.syncId;raw.actor=change.actor}}changeLog.push(change);for(const response of syncClients)response.write(`id: ${change.syncId}\nevent: change\ndata: ${JSON.stringify(change)}\n\n`);return change}
const publishFolder=()=>{const folder=folderDetails()[0];publish({entity:'folder',op:'put',key:folder.key,folder,actor:'imap'})}
const dist=resolve('dist')
const server=createServer(async(req,res)=>{
 try{
  const url=new URL(req.url,'http://localhost')
  if(url.pathname==='/favicon.ico'){res.writeHead(204);res.end();return}
  if(url.pathname==='/__reference'){
   const source=(await readFile('../docs/design/web-client.html','utf8')).replace(/<link[^>]+(?:fonts\.googleapis\.com|fonts\.gstatic\.com)[^>]*>/g,'')
   res.setHeader('Content-Type','text/html');res.end(source.replace('</head>','<style>'+await readFile('src/fonts.css','utf8')+'</style></head>'));return
  }
  res.setHeader('Content-Security-Policy',"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; font-src 'self' data:; img-src 'self' data: blob:; connect-src 'self'; frame-src 'self' blob:; worker-src 'self'; manifest-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'")
  if(networkDown&&url.pathname.startsWith('/api/')){req.socket.destroy();return}
  const json=(status,value)=>{res.writeHead(status,{'Content-Type':'application/json','Cache-Control':'no-store'});res.end(JSON.stringify(value))}
  let body='';for await(const chunk of req)body+=chunk
  const data=body?JSON.parse(body):null
  if(url.pathname==='/api/me')return json(signedIn?200:401,signedIn?account:{error:'login_required'})
  if(url.pathname==='/auth/login'){if(data.password!=='test-password')return json(401,{error:'invalid_credentials'});signedIn=true;return json(200,{next:'/'})}
  if(url.pathname==='/api/sessions')return json(200,[{agent:'Chrome Linux',current:true,expires:new Date(Date.now()+86400000).toISOString()}])
  if(url.pathname==='/api/mail/push'){if(req.method==='POST'){const device={id:'fixture-push',name:data.name,zone:data.zone};pushDevices.splice(0,pushDevices.length,device);return json(201,device)}return json(200,{publicKey:'B'+Buffer.alloc(64).toString('base64url'),devices:pushDevices})}
  if(url.pathname.startsWith('/api/mail/push/')&&req.method==='DELETE'){pushDevices.splice(0);return json(200,{})}
  if(url.pathname==='/api/mail/operations')return json(200,operationRenames)
  if(url.pathname==='/api/mail/operations/rename-fixture/cancel'){operationRenames.splice(0);return json(200,{})}
  if(url.pathname==='/api/mail/outbox/uncertain-fixture/restore'){const index=outbox.findIndex(job=>job.id==='uncertain-fixture'),job=outbox.splice(index,1)[0];return json(200,job.message)}
  if(url.pathname==='/api/mail/rules')return json(200,{digest:JSON.stringify(prefs.rules),applications:[],jobs:[]})
  if(url.pathname==='/api/mail/rules/preview'){const rule=data.rule,scanned=emails.filter(email=>(email.folder||'INBOX')==='INBOX'),matched=scanned.filter(email=>rule.conditions.every(condition=>{const value=String(({from:email.from,to:email.to.join(' '),subject:email.subject,'list-id':email.listId||''})[condition.field]).toLowerCase(),want=condition.value.toLowerCase();return condition.match==='equals'?value===want:condition.match==='ends'?value.endsWith(want):value.includes(want)}));return json(200,{scanned:scanned.length,matched:matched.length})}
  if(url.pathname==='/api/mail/rules/apply'){events.emit('apply-rules',data);return json(202,{id:'fixture-apply'})}
  if(url.pathname==='/api/clients')return json(200,clients)
  if(url.pathname.startsWith('/api/clients/')&&req.method==='DELETE'){clients.splice(0,clients.length);return json(200,{})}
  if(url.pathname.startsWith('/api/mail/')){
   if(!signedIn)return json(401,{error:'login_required'})
   if(req.headers['x-mail-owner']!==account.email||req.headers['x-mail-account']!==account.icloud_email)return json(403,{error:'wrong_account'})
   if(url.pathname==='/api/mail/sync/bootstrap'){
    res.writeHead(200,{'Content-Type':'application/x-ndjson'});res.write(JSON.stringify({type:'bootstrap',syncId:sequence,status:{phase:'live',mode:'IDLE + CONDSTORE',ready:true,imported:emails.length,total:emails.length},prefs})+'\n');for(const folder of folderDetails())res.write(JSON.stringify({type:'folder',folder})+'\n');for(const email of emails)res.write(JSON.stringify({type:'msg',message:metadata(email)})+'\n');res.end(JSON.stringify({type:'ready',syncId:sequence})+'\n');return
   }
   if(url.pathname==='/api/mail/sync/history')return json(200,{messages:emails.map(metadata),next:'',complete:true})
   if(url.pathname==='/api/mail/sync/stream'){
    res.writeHead(200,{'Content-Type':'text/event-stream','Cache-Control':'no-store'});res.write(': connected\n\n');for(const change of changeLog)if(change.syncId>Number(url.searchParams.get('cursor')))res.write(`id: ${change.syncId}\nevent: change\ndata: ${JSON.stringify(change)}\n\n`);syncClients.add(res);res.on('close',()=>syncClients.delete(res));return
   }
   if(url.pathname==='/api/mail/activity')return json(200,changeLog.filter(change=>change.actor?.startsWith('mcp:')))
   if(url.pathname.startsWith('/api/mail/activity/')&&url.pathname.endsWith('/undo')){const change=changeLog.find(change=>change.syncId===Number(url.pathname.split('/')[4])),email=emails.find(email=>email.id===change.message.id);email.flagColor=change.before.flagColor;publish({entity:'msg',op:'put',key:metadata(email).key,message:metadata(email),actor:'web'});return json(200,{})}
   if(url.pathname==='/api/mail/folders')return json(200,{folders:['INBOX','Archive','Drafts','Sent Messages','Junk','Deleted Messages','Clients']})
   if(url.pathname==='/api/mail/search'){const query=url.searchParams.get('q');await new Promise(resolve=>setTimeout(resolve,100));return json(200,{messages:emails.filter(email=>searchMatch(searchMessage(email,email.folder||'INBOX'),query,email.bodyPlain||email.bodyHTML||'')).map(metadata),syncId:sequence,next:'',more:false})}
   if(url.pathname==='/api/mail/messages')return json(200,{emails,total:emails.length})
   if(url.pathname==='/api/mail/message'){const email=emails.find(e=>e.id===url.searchParams.get('id'));return json(200,{bodyPlain:'Hi,\n\nPlease review the launch notes.\n\nThanks,\nMira',...email})}
   if(url.pathname==='/api/mail/remote-image'){remoteRequests++;assert.equal(data.url,'https://images.example.com/banner.png');res.writeHead(200,{'Content-Type':'image/png'});res.end(Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aDXkAAAAASUVORK5CYII=','base64'));return}
   if(url.pathname==='/api/mail/attachment'){const name=url.searchParams.get('filename'),image=name==='sample.png',pdf=name==='document.pdf';res.writeHead(200,{'Content-Type':url.searchParams.get('preview')==='1'?(image?'image/png':pdf?'application/pdf':'text/plain'):'application/octet-stream','Content-Disposition':'attachment; filename=notes.pdf'});res.end(image?Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aDXkAAAAASUVORK5CYII=','base64'):pdf?pdfFixture():'test attachment');return}
   if(url.pathname==='/api/mail/preferences'){if(['PUT','PATCH'].includes(req.method)){prefs=req.method==='PATCH'?{...prefs,...data}:data;publish({entity:'pref',op:'put',key:account.email,preferences:prefs,actor:'web'})};return json(200,prefs)}
   if(url.pathname==='/api/mail/mutate'){
    if(data.transactionId){const receipt=changeLog.find(change=>change.entity==='tx'&&change.txId===data.transactionId);if(receipt)return json(200,{syncId:receipt.syncId,txId:data.transactionId})}
    let email=emails.find(e=>e.id===data.id),publishMail=true
    const allFolders=()=>{for(const folder of folderDetails())publish({entity:'folder',op:'put',key:folder.key,folder,actor:'imap'})}
    const relocate=(email,target,transaction)=>{const before=metadata(email);email.threadId=before.threadId;email.folder=target;email.id=String(nextUID++);email.moveTransaction=transaction;publish({entity:'msg',op:'del',key:before.key,before,actor:'web',txId:data.transactionId});if(!folderNames.includes(target))folderNames.push(target)}
    if(data.op==='createFolder'){assert(!folderNames.includes(data.folder));folderNames.push(data.folder);publishMail=false}
    else if(data.op==='renameFolder'){assert(folderNames.includes(data.folder));const old=folderDetails().find(folder=>folder.name===data.folder);folderNames.splice(folderNames.indexOf(data.folder),1,data.target);publish({entity:'folder',op:'reset',key:old.key,folder:old,actor:'web'});publish({entity:'folder',op:'del',key:old.key,actor:'web'});publishMail=false}
    else if(data.op==='deleteFolder'){assert.equal(emails.filter(email=>email.folder===data.folder).length,0);folderNames.splice(folderNames.indexOf(data.folder),1);publish({entity:'folder',op:'del',key:'folder-'+data.folder,actor:'web'});publishMail=false}
    else if(data.op==='undoMove'){const move=moves.get(data.originalTransaction);assert(move);email=move.email;relocate(email,move.from,data.originalTransaction);delete email.snoozed;delete email.snoozeUntil}
    else{
     assert.equal(data.validity,7)
     if(data.op==='delete'){json(200,{syncId:sequence});events.emit('mutation',data);return}
     assert(email,`Missing UID ${data.id} for ${data.op} in ${data.folder}`)
     if(data.op==='flag')email.flagColor=data.color
     if(data.op==='read')email.unread=!data.read
     if(data.op==='move'||data.op==='snooze'){const target=data.op==='snooze'?'Snoozed':data.target;if(email.folder!==target){moves.set(data.transactionId,{email,from:email.folder||'INBOX'});relocate(email,target,data.transactionId)};if(data.op==='snooze'){email.snoozed=true;email.snoozeUntil=data.until}}
     if(data.op==='unsnooze'){const move=moves.get(email.moveTransaction);relocate(email,move?.from||'INBOX',data.transactionId);delete email.snoozed;delete email.snoozeUntil;email.unread=true}
    }
    if(publishMail)publish({entity:'msg',op:'put',key:metadata(email).key,message:metadata(email),actor:'web',txId:data.transactionId});allFolders();if(data.transactionId)publish({entity:'tx',op:'ack',key:data.transactionId,actor:'web',txId:data.transactionId});json(200,{syncId:sequence,txId:data.transactionId});events.emit('mutation',data);return
   }
   if(url.pathname==='/api/mail/draft')return json(200,{id:'100',folder:'Drafts',validity:7})
   if(url.pathname==='/api/mail/outbox'){
    if(req.method==='GET')return json(200,outbox)
    const job={id:crypto.randomUUID(),status:'pending',sendAt:new Date(Date.now()+10000).toISOString(),message:data};outbox.push(job);json(202,job);events.emit('send',job);return
   }
   if(url.pathname.startsWith('/api/mail/outbox/')&&req.method==='DELETE'){
    const i=outbox.findIndex(job=>job.id===url.pathname.split('/').at(-1));assert(i>=0);const[job]=outbox.splice(i,1);json(200,job.message);return
   }
   return json(404,{error:'unknown_test_endpoint'})
  }
  const path=resolve(dist,'.'+(url.pathname==='/'?'/index.html':url.pathname))
  assert(path.startsWith(dist+'/'))
  const file=await readFile(path)
  const type={'.html':'text/html','.js':'text/javascript','.mjs':'text/javascript','.css':'text/css','.ttf':'font/ttf','.png':'image/png','.webmanifest':'application/manifest+json'}[extname(path)]||'application/octet-stream'
  res.writeHead(200,{'Content-Type':type});res.end(file)
 }catch(err){res.writeHead(500);res.end(String(err));errors.push(String(err))}
})
